import sys
import json

try:
    data = json.load(open('/app/resources/treasury_bulletin_1972_04.json'))
    # Find tables
    def find_tables(obj, path=''):
        if isinstance(obj, dict):
            for k, v in obj.items():
                find_tables(v, f'{path}.{k}')
        elif isinstance(obj, list):
            for i, v in enumerate(obj):
                find_tables(v, f'{path}[{i}]')
        elif isinstance(obj, str):
            if 'exchange' in obj.lower() or 'germany' in obj.lower() or 'dem' in obj.lower():
                print(f'{path}: {obj[:100]}')

    find_tables(data)
except Exception as e:
